CREATE OR REPLACE FUNCTION public.lookup_registration(_protocol text,_email text,_ip text) RETURNS TABLE(full_name text,protocol text,form_title text,status public.reg_status,public_note text,created_at timestamptz,updated_at timestamptz,tracking_token uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.lookup_attempts a WHERE a.created_at<now()-interval '1 hour'; IF (SELECT count(*) FROM public.lookup_attempts a WHERE a.ip=_ip AND a.created_at>now()-interval '10 minutes')>=15 THEN RAISE EXCEPTION 'Muitas tentativas. Aguarde alguns minutos.'; END IF; INSERT INTO public.lookup_attempts(ip) VALUES(coalesce(_ip,'unknown')); RETURN QUERY SELECT r.full_name,r.protocol::text,f.title,r.status,r.public_note,r.created_at,r.updated_at,r.tracking_token FROM public.registrations r JOIN public.registration_forms f ON f.id=r.form_id WHERE r.protocol=_protocol AND lower(r.email)=lower(btrim(_email)) ORDER BY r.created_at DESC LIMIT 10; END $$; REVOKE ALL ON FUNCTION public.lookup_registration(text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.lookup_registration(text,text,text) TO service_role;